import java.nio.file.*;import java.io.*;
public class LogAnalyzer {public static void main(String[] args)throws Exception{Path dir=Paths.get("logs");Files.createDirectories(dir);Files.writeString(dir.resolve("one.txt"),"hello world\nerror found\nhello again\n");Files.writeString(dir.resolve("two.txt"),"normal line\nerror again\n");String key="error";int lines=0,matches=0;try(DirectoryStream<Path> ds=Files.newDirectoryStream(dir,"*.txt")){for(Path p:ds){long size=Files.size(p);try(BufferedReader br=Files.newBufferedReader(p)){String line;while((line=br.readLine())!=null){lines++;if(line.toLowerCase().contains(key))matches++;}}System.out.println(p.getFileName()+" size="+size);}}System.out.println("Lines: "+lines+", matches: "+matches);}}
